import{_ as i,l as o,o as a,c as l,v as r,p as s,x as n,d as u,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Abreu–Brunnermeier 同步失败","description":"","frontmatter":{"title":"Abreu–Brunnermeier 同步失败","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/abreu-brunnermeier.md","filePath":"econ/abreu-brunnermeier.md","lastUpdated":1789023840000}'),B={name:"econ/abreu-brunnermeier.md"};function d(A,e,m,c,b,h){const t=o("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="abreu–brunnermeier-同步失败" tabindex="-1">Abreu–Brunnermeier 同步失败 <a class="header-anchor" href="#abreu–brunnermeier-同步失败" aria-label="Permalink to &quot;Abreu–Brunnermeier 同步失败&quot;">​</a></h1><div class="epigraph"><p>套利者陆续知道泡沫存在，但不知道别人是不是已经知道；先动手的人独自承担价格还在涨的风险，于是都等，泡沫比消息更长寿。</p><footer>—— Abreu and Brunnermeier, Bubbles and Crashes, Econometrica 2003</footer></div><p><a href="/econ/rational-bubbles">上一课</a>留下「人人知道仍可能持有」。本课缺口是时机：专业套利者<strong>陆续</strong>意识到错定价，攻击需要同步。没有共同知识的那一天，各自动手都太早。不重写 \\(B=E[mB&#39;]\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Abreu 与 Brunnermeier（2003）：泡沫在某个未观测时点开始，套利者按随机顺序得到信号，知道「已经开始」但不知道自己在序列中的位置。卖空有资本约束（每人只能抛有限量），必须凑够数量才能刺破。每个人都想骑泡沫到接近破裂再动手（preemption 与 waiting 的权衡）。均衡是延迟：从第一个信号到崩盘有一段内生时间。缺口是给 <a href="/econ/limits-to-arbitrage">SV 套利限制</a>加上<strong>信息同步</strong>，而不是再写委托赎回。</p><p><span class="marginnote">共同知识比「人人知道」更强：人人知道人人知道……。泡沫可以在高阶信念缺口上存活。这是协调博弈，不是噪声交易者的随机需求。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>连续时间，信号到达的泊松或均匀顺序，资本加总阈值。策略：收到信号后等待 \\(\\tau\\) 再攻击。对称均衡 \\(\\tau\\gt 0\\)。比较静态：资本越分散、信号越不同步，延迟越长，泡沫越大。崩盘可以比基本面消息猛——因为同步一旦达成，资本同时到位。</p>',8)),(a(),s(E,null,{default:n(()=>[p(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E4%BF%A1%E5%8F%B7%E9%99%86%E7%BB%AD%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20CK%5B%22%E6%B2%A1%E6%9C%89%E5%85%B1%E5%90%8C%E7%9F%A5%E8%AF%86%E7%9A%84%E6%97%B6%E7%82%B9%22%5D%0A%20%20CK%20--%3E%20WAIT%5B%22%E6%80%95%E8%87%AA%E5%B7%B1%E5%8A%A8%E6%89%8B%E5%A4%AA%E6%97%A9%22%5D%0A%20%20WAIT%20--%3E%20DEL%5B%22%E5%9D%87%E8%A1%A1%E5%BB%B6%E8%BF%9F%3A%20%E6%B3%A1%E6%B2%AB%E8%B6%85%E5%AF%BF%22%5D%0A%20%20DEL%20--%3E%20CRASH%5B%22%E9%98%88%E5%80%BC%E5%87%91%E9%BD%90%3A%20%E5%B4%A9%E7%9B%98%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[u(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>不把「攻击」写成限价簿上的大单扫货。阈值是资本加总，协议仍属量化栏。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是协调失败。骑泡沫的收益是继续上涨；过早攻击的成本是被轧空或错过上涨。SV 的赎回在此换成「别人还没动手时价格继续涨」。DSSW 的噪声仍可以提供上涨；AB 即使在泡沫终将破裂的共同信念下，也能因不同步而延迟。与理性泡沫的差别：AB 的价格路径由行为或外生泡沫过程驱动，理论核心是刺破的博弈，不是齐次欧拉。</p><p>「人人知道价格太高」还不是共同知识：我不知道你是不是已经收到信号。先动手且别人未动，价格继续涨，自己被轧。对称均衡是等待一段内生时间。资本分散、信号不同步，则延迟拉长。不把攻击写成簿上的扫货；阈值是资本加总。主干在交接处停，本课仍是均衡时机，不是协议。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>若信号是公共公告（人人同时知道），同步问题消失，模型退回谁先抢的简单抢先。完全无卖空约束则一人即可刺破。本课不估计延迟长度。金融危机叙事可以当动机，不是识别。</p><p>后课默认：羊群与信息级联是另一条「看见别人的行动当信号」的协调；AB 是已经知情的人等别人一起动手。</p><p>陆续知情加资本阈值，均衡是等待：泡沫比第一条消息更长寿，崩盘是同步成功。</p><p>人人知道还不是共同知识。SV 是资本逃走；AB 是资本到了仍不下手。</p><p><span class="marginnote">公共同时公告则同步问题消失；一人可刺破则延迟消失。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>陆续知情 + 资本阈值 ⇒ 均衡等待，泡沫超寿。</li><li>崩盘是同步成功，不是基本面突然跳。</li><li>在 SV 的融资限制之上加上高阶信念缺口。</li><li>公共同时公告则同步问题消失。</li><li>一人即可刺破则延迟消失。</li><li>出处：Abreu and Brunnermeier, <em>Econometrica</em> 2003。</li></ul>',12))])}const S=i(B,[["render",d]]);export{f as __pageData,S as default};
